## D) `game/src/engine.hpp`
```cpp
#pragma once
#include <SFML/Graphics.hpp>
#include <vector>

struct Bullet {
    sf::Vector2f pos;
    sf::Vector2f vel;
    float life = 1.5f; // seconds
    float radius = 3.f;
};

struct Player {
    sf::Vector2f pos{640.f, 360.f};
    sf::Vector2f vel{0.f, 0.f};
    float speed = 220.f;   // px/s
    float radius = 10.f;
    float fireCooldown = 0.15f; // seconds between shots
    float fireTimer = 0.f;
};

class Engine {
public:
    Engine();
    void run();

private:
    void handleInput(float dt);
    void update(float dt);
    void render();

    void shootTowards(const sf::Vector2f& target);
    sf::Vector2f getMouseWorld() const;

private:
    sf::RenderWindow window_;
    sf::View view_;
    Player player_;
    std::vector<Bullet> bullets_;

    // simple shapes
    sf::CircleShape playerShape_;
    sf::CircleShape bulletShape_;

    // world/grid
    sf::RectangleShape tile_;
};
```

---

## E) `game/src/engine.cpp`
```cpp
#include "engine.hpp"
#include <cmath>

namespace {
    float length(sf::Vector2f v){ return std::sqrt(v.x*v.x + v.y*v.y); }
    sf::Vector2f normalize(sf::Vector2f v){
        float L = length(v); return (L>1e-6f) ? sf::Vector2f(v.x/L, v.y/L) : sf::Vector2f(0.f,0.f);
    }
}

Engine::Engine()
: window_(sf::VideoMode(1280, 720), "Death Circuit - Base Loop")
{
    window_.setFramerateLimit(120);
    view_.reset(sf::FloatRect(0.f, 0.f, 1280.f, 720.f));
    window_.setView(view_);

    // Player visual
    playerShape_.setRadius(player_.radius);
    playerShape_.setOrigin(player_.radius, player_.radius);
    playerShape_.setFillColor(sf::Color(50, 200, 255));

    // Bullet visual
    bulletShape_.setRadius(3.f);
    bulletShape_.setOrigin(3.f, 3.f);
    bulletShape_.setFillColor(sf::Color::Yellow);

    // Tile styling (for a simple background grid)
    tile_.setSize({32.f, 32.f});
    tile_.setFillColor(sf::Color(20, 20, 24));
    tile_.setOutlineColor(sf::Color(28, 28, 36));
    tile_.setOutlineThickness(1.f);
}

void Engine::run(){
    sf::Clock clock;
    while (window_.isOpen()){
        sf::Event e;
        while (window_.pollEvent(e)){
            if (e.type == sf::Event::Closed) window_.close();
        }

        float dt = clock.restart().asSeconds();
        handleInput(dt);
        update(dt);
        render();
    }
}

void Engine::handleInput(float dt){
    // Movement
    sf::Vector2f dir{0.f, 0.f};
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) dir.y -= 1.f;
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) dir.y += 1.f;
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::A)) dir.x -= 1.f;
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::D)) dir.x += 1.f;

    dir = normalize(dir);
    player_.vel = dir * player_.speed;
    player_.pos += player_.vel * dt;

    // Shooting (left mouse)
    player_.fireTimer -= dt;
    if (sf::Mouse::isButtonPressed(sf::Mouse::Left) && player_.fireTimer <= 0.f){
        shootTowards(getMouseWorld());
        player_.fireTimer = player_.fireCooldown; // reset
    }
}

void Engine::update(float dt){
    // Update bullets
    for (auto &b : bullets_){
        b.pos += b.vel * dt;
        b.life -= dt;
    }
    // Remove dead bullets
    bullets_.erase(
        std::remove_if(bullets_.begin(), bullets_.end(),
            [](const Bullet& b){ return b.life <= 0.f; }),
        bullets_.end()
    );
}

void Engine::render(){
    window_.clear(sf::Color(12,12,16));

    // Draw simple grid background
    const int cols = 1280 / 32 + 2;
    const int rows = 720  / 32 + 2;
    for (int y=0; y<rows; ++y){
        for (int x=0; x<cols; ++x){
            tile_.setPosition(x*32.f, y*32.f);
            window_.draw(tile_);
        }
    }

    // Draw player
    playerShape_.setPosition(player_.pos);
    window_.draw(playerShape_);

    // Draw bullets
    for (auto &b : bullets_){
        bulletShape_.setPosition(b.pos);
        window_.draw(bulletShape_);
    }

    window_.display();
}

sf::Vector2f Engine::getMouseWorld() const{
    auto mp = sf::Mouse::getPosition(window_);
    return window_.mapPixelToCoords(mp);
}

void Engine::shootTowards(const sf::Vector2f& target){
    sf::Vector2f dir = normalize(target - player_.pos);
    Bullet b;
    b.pos = player_.pos + dir * (player_.radius + 6.f);
    b.vel = dir * 420.f; // bullet speed
    b.life = 1.2f;
    bullets_.push_back(b);
}
```

