# ⚙️ STEP 2 — `main.cpp`

This file only **creates the engine** and starts the game. Nothing else.

```cpp
#include "Engine.hpp"

int main() {
    Engine game;
    game.run();
    return 0;
}
```

✅ **Explanation:**
- `Engine` is our main class that manages everything (window, loop, input, update, render).
- Keeping `main()` this clean ensures zero clutter.

---

# 🧠 STEP 3 — `Engine.hpp`

```cpp
#pragma once
#include <SFML/Graphics.hpp>
#include <vector>
#include "Player.hpp"
#include "Bullet.hpp"

class Engine {
public:
    Engine();
    void run(); // starts the game loop

private:
    void processEvents();
    void update(float dt);
    void render();

private:
    sf::RenderWindow window_;
    sf::Clock clock_;
    Player player_;
    std::vector<Bullet> bullets_;
};
```

✅ **Explanation:**
- `Engine` owns the window, time, player, and bullet list.  
- It’s responsible for game flow (input → update → render).

---

# ⚙️ STEP 4 — `Engine.cpp`

```cpp
#include "Engine.hpp"
#include <algorithm>

Engine::Engine()
: window_(sf::VideoMode(1280, 720), "Death Circuit")
{
    window_.setFramerateLimit(120);
}

void Engine::run() {
    while (window_.isOpen()) {
        processEvents();
        float dt = clock_.restart().asSeconds();
        update(dt);
        render();
    }
}

void Engine::processEvents() {
    sf::Event event;
    while (window_.pollEvent(event)) {
        if (event.type == sf::Event::Closed)
            window_.close();
    }
}

void Engine::update(float dt) {
    player_.update(dt, window_, bullets_);

    for (auto& b : bullets_) b.update(dt);
    bullets_.erase(
        std::remove_if(bullets_.begin(), bullets_.end(),
            [](const Bullet& b){ return !b.isAlive(); }),
        bullets_.end()
    );
}

void Engine::render() {
    window_.clear(sf::Color(10,10,15));
    player_.draw(window_);
    for (auto& b : bullets_) b.draw(window_);
    window_.display();
}
```

✅ **Explanation:**
| Method | Role |
|---------|------|
| `processEvents()` | Handles closing the window. |
| `update(dt)` | Updates player + all bullets, removes dead ones. |
| `render()` | Clears screen, draws everything, displays the frame. |
| `clock_.restart().asSeconds()` | Gives time delta per frame. |

---

# 🔵 STEP 5 — `Player.hpp`

```cpp
#pragma once
#include <SFML/Graphics.hpp>
#include <vector>
#include "Bullet.hpp"

class Player {
public:
    Player();

    void update(float dt, sf::RenderWindow& window, std::vector<Bullet>& bullets);
    void draw(sf::RenderWindow& window) const;

private:
    void handleInput(float dt, sf::RenderWindow& window, std::vector<Bullet>& bullets);
    void shoot(sf::Vector2f target, std::vector<Bullet>& bullets);

private:
    sf::CircleShape shape_;
    sf::Vector2f velocity_;
    float speed_;
    float fireCooldown_;
    float fireTimer_;
};
```

---

# 🔵 STEP 6 — `Player.cpp`

```cpp
#include "Player.hpp"
#include <cmath>

namespace {
    float length(sf::Vector2f v) { return std::sqrt(v.x*v.x + v.y*v.y); }
    sf::Vector2f normalize(sf::Vector2f v) {
        float len = length(v);
        return (len > 0.f) ? v / len : sf::Vector2f(0.f,0.f);
    }
}

Player::Player()
: speed_(240.f), fireCooldown_(0.18f), fireTimer_(0.f)
{
    shape_.setRadius(12.f);
    shape_.setOrigin(12.f, 12.f);
    shape_.setPosition(640.f, 360.f);
    shape_.setFillColor(sf::Color(70, 180, 255));
}

void Player::update(float dt, sf::RenderWindow& window, std::vector<Bullet>& bullets) {
    handleInput(dt, window, bullets);
    fireTimer_ -= dt;
}

void Player::handleInput(float dt, sf::RenderWindow& window, std::vector<Bullet>& bullets) {
    sf::Vector2f dir(0.f, 0.f);
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) dir.y -= 1.f;
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) dir.y += 1.f;
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::A)) dir.x -= 1.f;
    if (sf::Keyboard::isKeyPressed(sf::Keyboard::D)) dir.x += 1.f;

    dir = normalize(dir);
    shape_.move(dir * speed_ * dt);

    if (sf::Mouse::isButtonPressed(sf::Mouse::Left) && fireTimer_ <= 0.f) {
        sf::Vector2i mouse = sf::Mouse::getPosition(window);
        sf::Vector2f worldPos = window.mapPixelToCoords(mouse);
        shoot(worldPos, bullets);
        fireTimer_ = fireCooldown_;
    }
}

void Player::shoot(sf::Vector2f target, std::vector<Bullet>& bullets) {
    sf::Vector2f pos = shape_.getPosition();
    sf::Vector2f dir = normalize(target - pos);
    bullets.emplace_back(pos + dir * 14.f, dir * 500.f);
}

void Player::draw(sf::RenderWindow& window) const {
    window.draw(shape_);
}
```

✅ **Explanation Highlights:**
- `speed_`: player movement speed in pixels/sec.  
- `fireCooldown_`: delay between shots.  
- `fireTimer_`: countdown timer.  
- `handleInput()` moves player + fires bullets.  
- `shoot()` adds a bullet to shared vector.  

---

# 🔴 STEP 7 — `Bullet.hpp`

```cpp
#pragma once
#include <SFML/Graphics.hpp>

class Bullet {
public:
    Bullet(sf::Vector2f pos, sf::Vector2f vel);

    void update(float dt);
    void draw(sf::RenderWindow& window) const;
    bool isAlive() const { return lifetime_ > 0.f; }

private:
    sf::CircleShape shape_;
    sf::Vector2f velocity_;
    float lifetime_;
};
```

---

# 🔴 STEP 8 — `Bullet.cpp`

```cpp
#include "Bullet.hpp"

Bullet::Bullet(sf::Vector2f pos, sf::Vector2f vel)
: velocity_(vel), lifetime_(1.2f)
{
    shape_.setRadius(3.f);
    shape_.setOrigin(3.f, 3.f);
    shape_.setPosition(pos);
    shape_.setFillColor(sf::Color::Yellow);
}

void Bullet::update(float dt) {
    shape_.move(velocity_ * dt);
    lifetime_ -= dt;
}

void Bullet::draw(sf::RenderWindow& window) const {
    window.draw(shape_);
}
```

✅ **Explanation:**
- Bullets move each frame using velocity * dt.
- `lifetime_` decreases over time (auto-removes).
- Draws small yellow dots for bullets.

